// Default language: German when the system/browser language is German, else
// English. A stored choice wins; the server's language overrides it after the
// first state (app.js).
let LANG = /^de/i.test((typeof navigator !== "undefined" && navigator.language) || "") ? "de" : "en";
try { LANG = localStorage.getItem("lang") || LANG; } catch { /* storage blocked */ }

function t(key, vars) {
  let s = (STRINGS[LANG] && STRINGS[LANG][key]) ?? STRINGS.de[key] ?? key;
  for (const [k, v] of Object.entries(vars || {})) s = s.replaceAll(`{${k}}`, () => String(v));
  return s;
}

// Fixed server messages (English, from the API) shown in the interface language.
const SERVER_MSG = [
  [/lighting is (switched )?off/, "msg.lightingOff"], [/cooling is switched off/, "msg.coolingOff"],
  [/not available in the demo/, "msg.demo"], [/setup was cancelled or failed/, "msg.uacDeclined"],
  [/no pump ".*" on a mainboard header|the pump ".*" is not on a mainboard header|not a fan header of the mainboard/, "msg.pumpNotEligible"],
  [/is not released for CaseHUD/, "msg.pumpNotReleased"], [/has not been checked yet/, "msg.pumpNotChecked"], [/no fan on a curve to measure/, "msg.noFanToMeasure"],
  [/too hot to measure the pump/, "msg.pumpTooHot"], [/temperature sensor of the curves cannot be read/, "msg.pumpNoSensor"],
  [/a speed measurement is running/, "msg.measureRunning"], [/program is in charge/, "msg.fanProgram"],
  [/speeds can only be measured/, "msg.measureNeedsLive"], [/there is a preset with this name/, "msg.presetName"],
  [/^at most (\d+) presets/, "msg.presetMax", ["n"]], [/^no preset /, "msg.presetNone"],
  [/there is no cooling set up/, "msg.coolingUnset"], [/changed in the meantime/, "msg.revision"],
  [/(accept|confirm) the .* in the CaseHUD window first/, "msg.ackRequired"],
  [/fan controller (is closed|not found|is not active)|no fan controller found/, "msg.noController"],
  [/fan list is being read already/, "msg.listBusy"],
  [/a release was asked for a moment ago/, "msg.releaseWait"], [/is not waiting for a release/, "msg.pumpNotWaiting"],
];

function srvMsg(raw) {
  for (const [re, key, names] of SERVER_MSG) {
    const m = re.exec(raw);
    if (m) return t(key, Object.fromEntries((names || []).map((n, i) => [n, m[i + 1]])));
  }
  return raw;
}

/** @type {(sel: string) => any[]} */
const allOf = (sel) => [...document.querySelectorAll(sel)];

function applyI18n() {
  document.documentElement.lang = LANG;
  for (const e of allOf("[data-i18n]")) e.textContent = t(e.dataset.i18n);
  for (const e of allOf("[data-i18n-html]")) e.innerHTML = t(e.dataset.i18nHtml);
  for (const e of allOf("[data-i18n-title]")) { e.title = t(e.dataset.i18nTitle); if (e.hasAttribute("aria-label")) e.setAttribute("aria-label", e.title); }
  for (const e of allOf("[data-i18n-aria]")) e.setAttribute("aria-label", t(e.dataset.i18nAria));
  for (const e of allOf("[data-i18n-placeholder]")) e.placeholder = t(e.dataset.i18nPlaceholder);
  for (const b of allOf("[data-lang]")) b.classList.toggle("active", b.dataset.lang === LANG);
  if (typeof decorateHelp === "function") decorateHelp();
}

function setLang(l) {
  LANG = l;
  try { localStorage.setItem("lang", l); } catch { /* ignore */ }
  applyI18n();
}
